def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Extend patterns attached to the bottom of vertical 5-lines.
    for c in range(w):
        rows = [r for r in range(h) if g[r][c] == 5]
        if not rows:
            continue
        # Process each contiguous vertical run.
        runs = []
        run = [rows[0]]
        for r in rows[1:]:
            if r == run[-1] + 1:
                run.append(r)
            else:
                runs.append(run)
                run = [r]
        runs.append(run)
        for run in runs:
            top, bottom = run[0], run[-1]
            if c + 1 >= w:
                continue
            # Find the seed block immediately to the right of the run's bottom.
            k = 0
            for r in range(bottom, top - 1, -1):
                if any(g[r][x] != 0 for x in range(c + 1, w)):
                    k += 1
                else:
                    break
            if k == 0:
                continue
            pattern = [g[r][c + 1:] for r in range(bottom - k + 1, bottom + 1)]
            for r in range(top, bottom + 1):
                src = pattern[(r - top) % k]
                for x, val in enumerate(src, c + 1):
                    if val != 0:
                        g[r][x] = val

    # Extend patterns attached below horizontal 5-lines.
    for r in range(h):
        cols = [c for c in range(w) if g[r][c] == 5]
        if not cols:
            continue
        # Process each contiguous horizontal run.
        runs = []
        run = [cols[0]]
        for c in cols[1:]:
            if c == run[-1] + 1:
                run.append(c)
            else:
                runs.append(run)
                run = [c]
        runs.append(run)
        for run in runs:
            left, right = run[0], run[-1]
            if r + 1 >= h:
                continue
            # A seed is the vertical sequence below the run's left endpoint.
            k = 0
            for rr in range(r + 1, h):
                if g[rr][left] != 0:
                    k += 1
                else:
                    break
            if k == 0:
                continue
            pattern = [g[rr][left] for rr in range(r + 1, r + 1 + k)]
            for c in range(left, right + 1):
                for i, val in enumerate(pattern):
                    rr = r + 1 + i
                    if rr < h and val != 0:
                        g[rr][c] = val

    return g
